try {
  const ids = ["19:79","9:23","9:17","30:207","30:213","9:33","9:36"];
  const out = [];
  for (const id of ids) {
    const n = await figma.getNodeByIdAsync(id);
    if (!n) { out.push(id + " MISSING"); continue; }
    const dump = (node, depth) => {
      let s = "  ".repeat(depth) + node.name + " [" + node.type + "] @" + Math.round(node.x) + "," + Math.round(node.y) + " " + Math.round(node.width) + "x" + Math.round(node.height);
      if (node.type === "TEXT") s += " \"" + node.characters + "\"";
      out.push(s);
      if (node.children) for (const c of node.children) dump(c, depth+1);
    };
    dump(n, 0); out.push("---");
  }
  return out.join("\n");
} catch (e) { return "ERR: " + e.message; }

